def Scan(name, cols, rows):
    return {"op": "Scan", "name": name, "cols": list(cols), "rows": rows, "children": []}


def Filter(pred, sel, child, refs=(), det=True):
    return {"op": "Filter", "pred": pred, "sel": sel, "refs": list(refs),
            "det": det, "children": [child]}


def Join(cond, sel, left, right):
    return {"op": "Join", "cond": cond, "sel": sel, "children": [left, right]}


def Agg(groups, child):
    return {"op": "Agg", "groups": groups, "children": [child]}


def cols_out(n):
    if n["op"] in ("Scan", "Project"):
        return set(n["cols"])
    s = set()
    for c in n["children"]:
        s |= cols_out(c)
    return s


def rows_out(n):
    ch = [rows_out(c) for c in n["children"]]
    if n["op"] == "Scan":
        return n["rows"]
    if n["op"] == "Filter":
        return int(ch[0] * n["sel"])
    if n["op"] == "Join":
        return int(ch[0] * ch[1] * n["sel"])
    if n["op"] == "Agg":
        return n["groups"]
    return ch[0]


def processed(n):
    if n["op"] == "Scan":
        return n["rows"]
    return sum(rows_out(c) for c in n["children"])


def total_cost(n):
    return processed(n) + sum(total_cost(c) for c in n["children"])


def label(n):
    if n["op"] == "Scan":
        return n["name"] + " cols=" + str(n["cols"]) + " rows=" + str(n["rows"])
    if n["op"] == "Filter":
        return n["pred"] + " sel=" + str(n["sel"])
    if n["op"] == "Join":
        return n["cond"] + " sel=" + str(n["sel"])
    if n["op"] == "Agg":
        return "groups=" + str(n["groups"])
    return str(n["cols"])


def show(n, depth=0):
    print("  " * depth + n["op"] + " " + label(n) + "   out=" + str(rows_out(n)))
    for c in n["children"]:
        show(c, depth + 1)


def push_filter(n):
    """规则 PushDownPredicate：把 Filter 移到能提供其 refs 的那一侧之上。"""
    kids = [push_filter(c) for c in n["children"]]
    n = dict(n)
    n["children"] = kids
    if n["op"] == "Filter" and kids and kids[0]["op"] == "Join":
        c = kids[0]
        for i, side in enumerate(c["children"]):
            if set(n["refs"]) <= cols_out(side):
                inner = dict(n)
                inner["children"] = [side]
                nc = dict(c)
                nc["children"] = list(c["children"])
                nc["children"][i] = inner
                return nc
    return n


def fuse_into_scan(n):
    """规则 PushDownIntoDataSource：Filter 落在 Scan 之上时与其融合（分区裁剪/列式过滤）。"""
    kids = [fuse_into_scan(c) for c in n["children"]]
    n = dict(n)
    n["children"] = kids
    if n["op"] == "Filter" and kids and kids[0]["op"] == "Scan":
        s = dict(kids[0])
        s["rows"] = int(s["rows"] * n["sel"])
        return s
    return n


orders = Scan("orders", ["uid", "amount", "dept", "dt", "ts"], 1000000000)
users = Scan("users", ["uid", "city"], 100000)
p0 = Agg(10,
         Filter("dt='2026-01-01'", 0.001,
                Join("o.uid=u.uid", 1e-9, orders, users),
                refs=["dt"]))

print("== 原始逻辑计划 ==")
show(p0)
c0 = total_cost(p0)
print("原始计划总代价（参与计算的记录数） = " + str(c0))
print("Join 输出行数 = " + str(rows_out(p0["children"][0]["children"][0])))

p1 = push_filter(p0)
print("")
print("== 规则1 谓词下推（Filter 移到 Scan 之上，但未融合） ==")
show(p1)
c1 = total_cost(p1)
print("下推后总代价 = " + str(c1))
print("说明：此时 Scan 仍读全量 1000000000 行，代价反而略升 = " + str(c1 > c0))

p2 = fuse_into_scan(p1)
print("")
print("== 规则2 下推并融合进 Scan（分区裁剪 / Parquet 下推） ==")
show(p2)
c2 = total_cost(p2)
print("融合后总代价 = " + str(c2))
print("Join 输出行数 = " + str(rows_out(p2["children"][0])))

print("")
print("代价 原始 -> 下推 -> 融合: " + str(c0) + " -> " + str(c1) + " -> " + str(c2))
print("下推并融合后代价更低: " + str(c2 < c0))
print("代价下降倍数 = " + str(round(c0 / c2, 2)))
print("判据 Join 输出行数由 100000 降到 " + str(rows_out(p2["children"][0])) + ": " +
      str(rows_out(p2["children"][0]) < rows_out(p0["children"][0]["children"][0])))
